import{_ as t,o,c as i,ag as a}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"Debugging Mobile Apps","description":"","frontmatter":{},"headers":[],"relativePath":"guides/debugging-mobile.md","filePath":"guides/debugging-mobile.md","lastUpdated":1772297611000}'),s={name:"guides/debugging-mobile.md"};function n(r,e,l,c,p,d){return o(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="debugging-mobile-apps" tabindex="-1">Debugging Mobile Apps <a class="header-anchor" href="#debugging-mobile-apps" aria-label="Permalink to &quot;Debugging Mobile Apps&quot;">​</a></h1><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 15 minutes</p><p>This tutorial shows you how to capture and inspect HTTP/HTTPS traffic from iOS and Android devices using NectoProxy. By routing your phone&#39;s traffic through NectoProxy, you can see every API call, debug network issues, and even mock or modify responses on the fly.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>NectoProxy installed on your computer</li><li>Your computer and mobile device connected to the <strong>same Wi-Fi network</strong></li><li>Physical access to the mobile device you want to debug</li></ul><h2 id="step-1-start-nectoproxy-with-network-access" tabindex="-1">Step 1: Start NectoProxy with Network Access <a class="header-anchor" href="#step-1-start-nectoproxy-with-network-access" aria-label="Permalink to &quot;Step 1: Start NectoProxy with Network Access&quot;">​</a></h2><p>By default, NectoProxy only listens on <code>127.0.0.1</code> (localhost), which means only your computer can use it. To allow your phone to connect, you need to bind to all network interfaces:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Binding to <code>0.0.0.0</code> exposes the proxy to your entire local network. Only do this on trusted networks (e.g., your home or office Wi-Fi). Never do this on public Wi-Fi.</p></div><h2 id="step-2-find-your-computer-s-ip-address" tabindex="-1">Step 2: Find Your Computer&#39;s IP Address <a class="header-anchor" href="#step-2-find-your-computer-s-ip-address" aria-label="Permalink to &quot;Step 2: Find Your Computer&#39;s IP Address&quot;">​</a></h2><p>You need your computer&#39;s local IP address so your phone knows where to send traffic. NectoProxy shows available addresses in the Settings panel.</p><h3 id="via-the-web-ui" tabindex="-1">Via the Web UI <a class="header-anchor" href="#via-the-web-ui" aria-label="Permalink to &quot;Via the Web UI&quot;">​</a></h3><ol><li>Open the NectoProxy Web UI at <code>http://localhost:8889</code>.</li><li>Click the <strong>gear icon</strong> to open Settings.</li><li>Scroll down to the <strong>Mobile Configuration</strong> section.</li><li>Your computer&#39;s IP addresses and network interfaces are listed there (e.g., <code>192.168.1.42</code>).</li></ol><h3 id="via-the-terminal" tabindex="-1">Via the Terminal <a class="header-anchor" href="#via-the-terminal" aria-label="Permalink to &quot;Via the Terminal&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ifconfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;inet &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> findstr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;IPv4&quot;</span></span></code></pre></div><p>Look for an address on your local network, typically starting with <code>192.168.</code>, <code>10.</code>, or <code>172.16-31.</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you have multiple network interfaces (e.g., Ethernet and Wi-Fi), use the IP address of the interface that is on the same network as your phone.</p></div><h2 id="step-3-configure-your-phone-s-wi-fi-proxy" tabindex="-1">Step 3: Configure Your Phone&#39;s Wi-Fi Proxy <a class="header-anchor" href="#step-3-configure-your-phone-s-wi-fi-proxy" aria-label="Permalink to &quot;Step 3: Configure Your Phone&#39;s Wi-Fi Proxy&quot;">​</a></h2><h3 id="ios-iphone-ipad" tabindex="-1">iOS (iPhone / iPad) <a class="header-anchor" href="#ios-iphone-ipad" aria-label="Permalink to &quot;iOS (iPhone / iPad)&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> on your iPhone.</li><li>Tap <strong>Wi-Fi</strong>.</li><li>Tap the <strong>info button (i)</strong> next to your connected Wi-Fi network.</li><li>Scroll down to <strong>HTTP Proxy</strong> and tap <strong>Configure Proxy</strong>.</li><li>Select <strong>Manual</strong>.</li><li>Enter: <ul><li><strong>Server:</strong> Your computer&#39;s IP address (e.g., <code>192.168.1.42</code>)</li><li><strong>Port:</strong> <code>8888</code> (or your custom proxy port)</li><li><strong>Authentication:</strong> Leave off</li></ul></li><li>Tap <strong>Save</strong>.</li></ol><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> on your Android device.</li><li>Tap <strong>Network &amp; Internet</strong> (or <strong>Wi-Fi</strong>, depending on your device).</li><li>Long-press on your connected Wi-Fi network, then tap <strong>Modify network</strong> (or tap the gear icon).</li><li>Tap <strong>Advanced options</strong> (or expand advanced settings).</li><li>Change <strong>Proxy</strong> from <strong>None</strong> to <strong>Manual</strong>.</li><li>Enter: <ul><li><strong>Proxy hostname:</strong> Your computer&#39;s IP address (e.g., <code>192.168.1.42</code>)</li><li><strong>Proxy port:</strong> <code>8888</code></li><li><strong>Bypass proxy for:</strong> Leave empty</li></ul></li><li>Tap <strong>Save</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The exact steps vary slightly between Android manufacturers (Samsung, Pixel, OnePlus, etc.). The general flow is the same: Wi-Fi settings, select your network, set proxy to Manual, and enter the IP and port.</p></div><h2 id="step-4-install-the-ca-certificate" tabindex="-1">Step 4: Install the CA Certificate <a class="header-anchor" href="#step-4-install-the-ca-certificate" aria-label="Permalink to &quot;Step 4: Install the CA Certificate&quot;">​</a></h2><p>Without the CA certificate, your phone will show security errors for all HTTPS traffic. NectoProxy provides two convenient ways to install the certificate.</p><h3 id="method-a-qr-code-recommended" tabindex="-1">Method A: QR Code (Recommended) <a class="header-anchor" href="#method-a-qr-code-recommended" aria-label="Permalink to &quot;Method A: QR Code (Recommended)&quot;">​</a></h3><ol><li>In the NectoProxy Web UI, open <strong>Settings</strong> (gear icon).</li><li>Scroll down to <strong>Mobile Configuration</strong>.</li><li>A <strong>QR Code</strong> is displayed that links to the certificate download URL.</li><li>Open the <strong>Camera app</strong> on your phone and point it at the QR code.</li><li>Tap the notification/link that appears to open it in the browser.</li><li>Follow the prompts to download and install the certificate.</li></ol><h3 id="method-b-manual-url" tabindex="-1">Method B: Manual URL <a class="header-anchor" href="#method-b-manual-url" aria-label="Permalink to &quot;Method B: Manual URL&quot;">​</a></h3><ol><li><p>On your phone&#39;s browser (with the proxy already configured), navigate to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;your-computer-ip&gt;:8889/api/certificates/download</span></span></code></pre></div><p>For example: <code>http://192.168.1.42:8889/api/certificates/download</code></p></li><li><p>The certificate file will download.</p></li></ol><h3 id="installing-the-downloaded-certificate" tabindex="-1">Installing the Downloaded Certificate <a class="header-anchor" href="#installing-the-downloaded-certificate" aria-label="Permalink to &quot;Installing the Downloaded Certificate&quot;">​</a></h3><h4 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h4><ol><li>After downloading, a prompt appears asking to install the profile. Tap <strong>Allow</strong>.</li><li>Go to <strong>Settings</strong> &gt; <strong>General</strong> &gt; <strong>VPN &amp; Device Management</strong> (or <strong>Profile &amp; Device Management</strong>).</li><li>Tap the <strong>NectoProxy CA</strong> profile and tap <strong>Install</strong>.</li><li>Enter your passcode if prompted, then tap <strong>Install</strong> again.</li><li><strong>Important:</strong> Go to <strong>Settings</strong> &gt; <strong>General</strong> &gt; <strong>About</strong> &gt; <strong>Certificate Trust Settings</strong>.</li><li>Toggle <strong>Enable Full Trust</strong> for the NectoProxy CA certificate.</li></ol><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>On iOS, you must complete both steps: installing the profile AND enabling full trust. The certificate will not work for HTTPS interception until full trust is enabled.</p></div><h4 id="android-1" tabindex="-1">Android <a class="header-anchor" href="#android-1" aria-label="Permalink to &quot;Android&quot;">​</a></h4><ol><li>After downloading, you may see a prompt to install the certificate. If so, follow it.</li><li>If no prompt appears, go to <strong>Settings</strong> &gt; <strong>Security</strong> (or <strong>Security &amp; Privacy</strong>) &gt; <strong>Encryption &amp; Credentials</strong> &gt; <strong>Install a certificate</strong> &gt; <strong>CA certificate</strong>.</li><li>Select the downloaded certificate file.</li><li>Confirm the installation.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>On Android 7.0 (Nougat) and later, user-installed CA certificates are not trusted by apps by default. Apps must explicitly opt in via their network security configuration. System apps and browsers will work, but some apps may still reject the certificate. For those apps, add the domain to SSL passthrough in NectoProxy settings.</p></div><h2 id="step-5-browse-on-your-phone" tabindex="-1">Step 5: Browse on Your Phone <a class="header-anchor" href="#step-5-browse-on-your-phone" aria-label="Permalink to &quot;Step 5: Browse on Your Phone&quot;">​</a></h2><p>With the proxy configured and the CA certificate installed, open any app or browser on your phone. You should see traffic appearing in the NectoProxy Web UI in real time.</p><p>Things to verify:</p><ul><li>HTTP requests appear immediately in the traffic list.</li><li>HTTPS requests appear with full URL, headers, and bodies (not just the CONNECT tunnel).</li><li>The phone&#39;s browser does not show certificate errors for standard websites.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If traffic is not appearing, double-check:</p><ol><li>Your phone is on the <strong>same Wi-Fi network</strong> as your computer.</li><li>The proxy settings are saved (try opening a website in the phone&#39;s browser).</li><li>NectoProxy was started with <code>--host 0.0.0.0</code>.</li><li>Your computer&#39;s firewall is not blocking port 8888.</li></ol></div><h2 id="step-6-using-the-qr-code-feature" tabindex="-1">Step 6: Using the QR Code Feature <a class="header-anchor" href="#step-6-using-the-qr-code-feature" aria-label="Permalink to &quot;Step 6: Using the QR Code Feature&quot;">​</a></h2><p>The QR code in the Settings panel encodes the certificate download URL. This is the fastest way to get the certificate onto your phone:</p><ol><li>Open NectoProxy Settings (gear icon).</li><li>If you have multiple network interfaces, select the correct one from the dropdown above the QR code.</li><li>Point your phone&#39;s camera at the QR code.</li><li>The URL resolves to <code>http://&lt;ip&gt;:&lt;uiPort&gt;/api/certificates/download</code>.</li></ol><p>The QR code updates automatically when you change the selected IP address or UI port.</p><h2 id="cleaning-up" tabindex="-1">Cleaning Up <a class="header-anchor" href="#cleaning-up" aria-label="Permalink to &quot;Cleaning Up&quot;">​</a></h2><p>When you are done debugging, remember to:</p><ol><li><strong>Remove the proxy settings</strong> from your phone&#39;s Wi-Fi configuration (set proxy back to <strong>None</strong>).</li><li><strong>Optionally remove the CA certificate</strong> from your phone if you no longer need it.</li></ol><h3 id="removing-the-ca-certificate" tabindex="-1">Removing the CA Certificate <a class="header-anchor" href="#removing-the-ca-certificate" aria-label="Permalink to &quot;Removing the CA Certificate&quot;">​</a></h3><p><strong>iOS:</strong> Settings &gt; General &gt; VPN &amp; Device Management &gt; NectoProxy CA &gt; Remove Profile</p><p><strong>Android:</strong> Settings &gt; Security &gt; Encryption &amp; Credentials &gt; Trusted Credentials &gt; User tab &gt; NectoProxy CA &gt; Remove</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Leaving the proxy settings configured on your phone after stopping NectoProxy will cause your phone to lose internet connectivity, because it will try to route all traffic through a proxy that no longer exists.</p></div><h2 id="tips-for-mobile-debugging" tabindex="-1">Tips for Mobile Debugging <a class="header-anchor" href="#tips-for-mobile-debugging" aria-label="Permalink to &quot;Tips for Mobile Debugging&quot;">​</a></h2><ul><li><strong>Use the filter bar</strong> in NectoProxy to focus on traffic from your app&#39;s API domain, reducing noise from background system requests.</li><li><strong>Create mock rules</strong> for APIs your mobile app calls to test edge cases without modifying server code.</li><li><strong>Use SSL Passthrough</strong> for domains you do not need to inspect (e.g., analytics, crash reporting). This avoids certificate pinning issues with SDKs that do not trust user-installed CAs.</li><li><strong>Check the WebSocket tab</strong> if your mobile app uses real-time communications. WebSocket frames are captured alongside regular HTTP traffic.</li></ul>`,54)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
